/* OAC FieldOps v10 — client-side encrypted guided workflow. No dependencies/network calls. */
(() => {
'use strict';
const C=window.OAC9,V=window.OAC10,$=q=>document.querySelector(q), E=C.esc;
const KEY='oac.fieldops.v10.encrypted', OLD='oac.fieldops.v9',ITER=310000;
const te=new TextEncoder(),td=new TextDecoder();
let state=null,passKey=null,route='overview',platform='powershell',busy=false,toastTimer=null,selectedProofTarget='',guideIP='172.16.24.1';
const stamp=()=>new Date().toISOString().slice(0,19).replace(/[:T]/g,'-');
const arr=x=>Array.from(x||[]),bytesToB64=b=>{let s='';for(const n of new Uint8Array(b))s+=String.fromCharCode(n);return btoa(s);};
const b64ToBytes=b=>Uint8Array.from(atob(b),c=>c.charCodeAt(0));
const rand=n=>crypto.getRandomValues(new Uint8Array(n));
async function derive(pass,salt){let raw=await crypto.subtle.importKey('raw',te.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITER,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function seal(key,salt,data){const iv=rand(12),plain=te.encode(JSON.stringify(data)),enc=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:te.encode('OAC-FIELDOPS-10')},key,plain);return JSON.stringify({version:10,kdf:'PBKDF2-SHA256',iterations:ITER,salt:bytesToB64(salt),iv:bytesToB64(iv),ciphertext:bytesToB64(enc)});}
async function openVault(pass,serialized){const item=JSON.parse(serialized);if(item.version!==10||!item.salt||!item.iv||!item.ciphertext)throw Error('Not a v10 encrypted backup');const salt=b64ToBytes(item.salt),key=await derive(pass,salt);const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(item.iv),additionalData:te.encode('OAC-FIELDOPS-10')},key,b64ToBytes(item.ciphertext));const data=JSON.parse(td.decode(raw));if(data.version!==10||!Array.isArray(data.hosts)||!Array.isArray(data.uploads))throw Error('Encrypted data failed validation');return {data,key,salt};}
let saltForSession=null,writePromise=Promise.resolve();
async function commit(){if(!state||!passKey)return;const snapshot=JSON.parse(JSON.stringify(state)),key=passKey,salt=saltForSession;const next=writePromise.catch(()=>{}).then(async()=>{try{const encrypted=await seal(key,salt,snapshot);localStorage.setItem(KEY,encrypted);}catch(err){alert('Encrypted vault could not be saved. Storage may be full. Export your current backup and keep the original loot files. '+err.message);throw err;}});writePromise=next;await next;}
async function mutate(fn){if(busy)return;busy=true;try{await fn();await commit();render();}catch(err){alert('Action failed: '+err.message);console.error(err);}finally{busy=false;}}
function toast(s){const el=$('#toast');if(!el)return;el.textContent=s;el.classList.add('shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('shown'),5500);}
function download(name,text,type='text/plain'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);}
function rawTotal(){return Object.values(state?.raw||{}).reduce((n,x)=>n+x.length,0);}
function oldDataExists(){return Boolean(localStorage.getItem(OLD));}
function lockedView(){const exists=!!localStorage.getItem(KEY);$('#auth').hidden=false;$('#shell').hidden=true;$('#auth').innerHTML=`<div class="unlock-wrap"><div class="unlock-story"><div class="monogram big">OAC<span>///</span></div><div class="eyebrow">FIELDOPS / V10 · ENCRYPTED WORKSPACE</div><h1>Your guided network assessment, <em>start to finish.</em></h1><p>Scope → Shark Jack → Transfer loot → Import → Investigate → Verify → Report. Your assessment stays inside your browser in an encrypted vault.</p><div class="unlock-steps">01 Authorization & consent<br>02 Shark Jack payloads and loot extraction<br>03–05 Evidence-driven PowerShell/Kali guidance<br>06 Approved proof and impact<br>07 Automatic evidence-linked report</div></div><form id="vaultForm" class="unlock-card"><div class="eyebrow">${exists?'VAULT / UNLOCK':'VAULT / FIRST-TIME SETUP'}</div><h2>${exists?'Unlock your workspace':'Create an encrypted workspace'}</h2><p>${exists?'Use the passphrase you chose for this v10 vault.':'Choose a passphrase of at least 10 characters. No account or cloud storage is involved.'}</p><label class="form-label">Vault passphrase<input name="pass" type="password" autocomplete="${exists?'current-password':'new-password'}" minlength="10" required placeholder="Enter passphrase"></label>${exists?'':`<label class="form-label">Confirm passphrase<input name="confirm" type="password" minlength="10" autocomplete="new-password" required placeholder="Repeat passphrase"></label>`}<button class="btn primary block" type="submit">${exists?'Unlock FieldOps →':'Create secure vault →'}</button><div class="callout blue">Your passphrase is not uploaded or stored. A forgotten passphrase cannot be recovered. Keep an encrypted backup.</div><div class="tiny">The previous v9 local workspace is not deleted; you may optionally import its data after unlocking.</div></form></div>`;}
async function authenticate(form){let p=new FormData(form).get('pass')||'';if(p.length<10)throw Error('At least 10 characters required');if(localStorage.getItem(KEY)){const item=await openVault(p,localStorage.getItem(KEY));state=item.data;passKey=item.key;saltForSession=item.salt;}else{if(p!==new FormData(form).get('confirm'))throw Error('Passphrases do not match');state=V.newState();saltForSession=rand(16);passKey=await derive(p,saltForSession);await commit();}p='';$('#auth').hidden=true;$('#shell').hidden=false;render();}
function lock(){state=null;passKey=null;saltForSession=null;route='overview';lockedView();}
function topHero(k,title,body){return `<div class="hero"><div><div class="eyebrow">${E(k)}</div><h1>${E(title)}</h1><p>${E(body)}</p></div><span class="tag good">V10 GUIDED</span></div>`;}
function status(s){const m={done:['good','EVIDENCE RECEIVED'],ready:['review','NEXT TO RUN'],inconclusive:['info','INCONCLUSIVE'],'needs-scope':['bad','AUTHORIZATION REQUIRED'],review:['review','REVIEW REQUIRED'],observed:['good','OBSERVED INDICATOR']};const [cls,label]=m[s]||['muted',(s||'PENDING').toUpperCase()];return `<span class="tag ${cls}">${label}</span>`;}
function copyButton(id){return `<button class="btn small" data-copy="${E(id)}">Copy command</button>`;}
const cmdMap=new Map();
function codeCard(command,title,where,why,filename){if(!command)return `<div class="callout">No command available. First document target ownership, consent and authorized scope in Phase 01.</div>`;const id='cmd'+cmdMap.size;cmdMap.set(id,command);return `<div class="command"><div class="command-head"><strong>${E(title)} · ${E(where)}</strong>${copyButton(id)}</div><pre>${E(command)}</pre></div><p class="caption">${E(why)}${filename?` Expected file: <code>${E(filename)}</code>.`:''}</p>`;}
function platformPicker(){return `<div class="actions platform-tabs"><span class="fine">Run commands on:</span><button data-platform="powershell" class="btn small ${platform==='powershell'?'primary':''}">Windows PowerShell</button><button data-platform="kali" class="btn small ${platform==='kali'?'primary':''}">Kali Linux</button></div>`;}
function metrics(){const rpt=V.report(state);return `<div class="grid four section"><div class="card metric"><small>IMPORTED FILES</small><b>${state.uploads.length}</b><em>Shark Jack / Nmap / proof logs</em></div><div class="card metric"><small>DISCOVERED HOSTS</small><b>${state.hosts.length}</b><em>${rpt.inScope.length} in authorized scope</em></div><div class="card metric"><small>OPEN SERVICES</small><b>${rpt.allPorts.length}</b><em>Needs evidence-based interpretation</em></div><div class="card metric"><small>REVIEW INDICATORS</small><b>${rpt.all.length}</b><em>${rpt.verified.length} observed; ${rpt.review.length} unverified</em></div></div>`;}
function navButton(route,text){return `<button class="btn ghost" data-route="${route}">${E(text)} →</button>`;}
function actionAdvice(){if(!V.authorize(state))return {route:'p01',label:'01 · Document ownership and authorization',why:'Record scope and consent before receiving target-specific scan commands.'};if(!state.uploads.length)return {route:'p02',label:'02 · Run your Shark Jack payloads, then transfer loot',why:'The app needs evidence before it can pick the next host-specific step.'};let h=V.hostTargets(state);if(!h.length)return {route:'p03',label:'03 · Verify hosts within your approved range',why:'Current loot has no recognizable in-scope assets.'};let p3=hostVerifyTasks();if(p3.some(t=>t.status==='ready'))return {route:'p03',label:'03 · Verify recognized hosts and ports',why:'Shark Jack discovery produced targets. Now gather precise service evidence.'};let p4=serviceTasks();if(p4.some(t=>t.status==='ready'||t.status==='inconclusive'))return {route:'p04',label:'04 · Investigate service configuration',why:'The imported host/port inventory determines which protocol-specific Nmap checks are needed.'};if(C.findings(state).length)return {route:'p05',label:'05 · Validate the security indicators',why:'Some checks suggest configuration problems or patch review; verify evidence before deciding if exploitation is warranted.'};return {route:'p07',label:'07 · Review final report',why:'No supported exploitable weakness was established. Finalize with a truthful limitations section.'};}
function overview(){const next=actionAdvice();return topHero('FIELDOPS / MISSION CONTROL','The tool tells you the next move.','You handle the authorization and run commands; FieldOps reads the imported logs and determines the next supported check.')+metrics()+`<div class="grid two section"><div class="card"><div class="eyebrow">NEXT ACTION</div><h2>${E(next.label)}</h2><p>${E(next.why)}</p>${navButton(next.route,'Open instructions')}</div><div class="card"><div class="eyebrow">ASSESSMENT STATUS</div><div class="phase-list">${[['p01','01','Scope & consent',V.authorize(state)],['p02','02','Shark Jack loot',state.uploads.length>0],['p03','03','Hosts identified',V.hostTargets(state).length>0],['p04','04','Service inventory',V.hostTargets(state).some(h=>h.ports.some(p=>p.state==='open'))],['p05','05','Validation evidence',serviceTasks().some(x=>x.status==='done')],['p06','06','Proof review',(state.proofs||[]).length>0],['p07','07','Report available',state.uploads.length>0]].map(([key,num,name,done])=>`<button class="phase-row" data-route="${key}"><strong>${num}</strong><span>${name}</span>${done?'<span class="tiny">✓</span>':'<span class="tiny">Not completed</span>'}</button>`).join('')}</div></div></div><div class="card section"><h2>What is automated—and what isn't</h2><p>FieldOps parses supported XML/text evidence, creates an inventory, explains observed facts, selects non-destructive follow-up checks, links output to targets and drafts the report. It cannot directly execute Nmap/Kali commands, independently establish network ownership, look up live CVEs, or prove that an exploit succeeded solely from a service banner. A legitimate proof claim requires an approved test and supporting output.</p></div>`;}
function authView(){let x=state.engagement;return topHero('PHASE 01 / AUTHORIZATION','Define exactly what may be tested.','Only enter basic details once. Subsequent commands are limited to the recorded IPv4 scope.')+`<div class="card section"><form id="authDetails" class="v10-form"><div class="grid two"><label class="form-label">Assessment name<input required name="name" value="${E(x.name)}" placeholder="Home Lab Practice"></label><label class="form-label">Owner / client<input required name="owner" value="${E(x.owner)}" placeholder="Self / authorized client"></label><label class="form-label">Assessor<input name="operator" value="${E(x.operator||'')}" placeholder="Your name / initials"></label><label class="form-label">Assessment date<input type="date" name="date" value="${E(x.date||new Date().toISOString().slice(0,10))}"></label><label class="form-label">IPv4 CIDR or individual hosts<input required name="scope" value="${E(x.scope)}" placeholder="10.10.10.0/24"></label><label class="form-label">Authorization basis<select name="authorizationType"><option value="self" ${x.authorizationType==='self'?'selected':''}>I own/control these systems</option><option value="client" ${x.authorizationType==='client'?'selected':''}>Client written permission</option></select></label></div><label class="form-label">Consent record / agreement reference<input required name="consentRecord" value="${E(x.consentRecord||'')}" placeholder="Owned home lab or signed SOW reference"></label><label class="form-label">Authorized activities<select name="approval"><option ${x.approval.includes('Read-only')?'selected':''}>Read-only discovery, enumeration and low-impact validation</option><option ${!x.approval.includes('Read-only')?'selected':''}>Discovery, enumeration, validation and separately approved controlled proof</option></select></label><label class="form-label">Excluded systems or activities<input name="exclusions" value="${E(x.exclusions||'')}" placeholder="Optional exclusions or testing windows"></label><label class="check-line"><input type="checkbox" name="authorized" ${x.authorized?'checked':''}> I confirm that I own or have explicit written permission to test the listed scope. I will not test another network without authorization.</label><label class="check-line"><input type="checkbox" name="proofApproved" ${x.proofApproved?'checked':''}> Controlled exploitation/proof is explicitly approved for the authorized lab or written engagement (optional).</label><button class="btn primary" type="submit">Save authorization & continue →</button></form><div class="callout ${V.authorize(state)?'green':'blue'} section">${V.authorize(state)?'Authorization record complete. Commands for in-scope hosts can be shown.': 'Fill owner, IPv4 scope and consent record, then confirm authorization to unlock target-specific commands.'}</div><p class="tiny">For clients, a checkbox is NOT a substitute for signed authorization. Your external contract must define permitted techniques, testing windows and rules of engagement. This local record is not a digital signature.</p></div>${navButton('p02','Next: Shark Jack')}`;}
function commandForTransfer(ip,os,part){if(os==='powershell'){if(part==='inspect')return `$SharkIP='${ip}'\nssh "root@$SharkIP" 'hostname; find /root/loot -type f 2>/dev/null | sort'\n# If no files appear, run your payload first and check its saved-loot location.`;return `$SharkIP='${ip}'\n$Dest=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'FieldOps-Loot\\SharkJack'\nNew-Item -ItemType Directory -Force -Path $Dest | Out-Null\nscp -O -r "root@${ip}:/root/loot/." "$Dest"\nGet-ChildItem -Path $Dest -Recurse -File | Select-Object FullName,Length\n# If your Display uses a different loot directory, replace /root/loot/. with the path found in step 1.`;}
if(part==='inspect')return `ssh root@${ip} 'hostname; find /root/loot -type f 2>/dev/null | sort'\n# Look for actual files. Your Display model/firmware may use a different path.`;return `mkdir -p "$HOME/FieldOps-Loot/SharkJack"\nscp -O -r root@${ip}:/root/loot/. "$HOME/FieldOps-Loot/SharkJack/"\nfind "$HOME/FieldOps-Loot/SharkJack" -type f | sort\n# For a different remote loot directory, use the actual full path.`;}
function payloads(){const steps=[['Simple Connection Test','Confirm the Shark Jack obtained network access and can reach its configured gateway.','A response or DHCP lease; if no IP, check cable, uplink mode, and whether this is the approved network.'],['Advanced Ping Test','Ping the authorized gateway or other known approved IP.','Reachability from the Shark Jack’s network position; no response does not imply the host is down.'],['Host Discovery / Network Scan','List responding hosts on the permitted subnet.','Save host-discovery XML/TXT to /root/loot where supported.'],['Port Scan / Port Sweep','Identify open listening ports on discovered approved hosts.','Host + port + state. Open does not equal vulnerable.'],['Service Scan / Network Hunter','Attempt service/version identification on relevant approved hosts.','Service names, fingerprints and if possible original Nmap XML.'],['Optional targeted checks','Only use specific follow-up payloads when FieldOps asks for them.','Evidence is linked to the matching IP/port; no automatic exploitation.']];return `<div class="card section"><div class="eyebrow">SELECT PAYLOADS ON YOUR SHARK JACK DISPLAY</div><h2>Run them in this order</h2><p>Use the closest built-in payload name on your actual firmware; the labels vary by library version. Do not install our previously broken custom payloads. On each run, wait for payload completion, then save any resulting loot.</p><div class="phase-list">${steps.map((r,i)=>`<div class="payload-card"><span class="payload-no">${String(i+1).padStart(2,'0')}</span><div><strong>${E(r[0])}</strong><p>${E(r[1])}</p><div class="tiny">Expected: ${E(r[2])}</div></div></div>`).join('')}</div></div>`;}
function sharkView(){return topHero('PHASE 02 / SHARK JACK','Run payloads → retrieve loot → upload.','A hands-on checklist with copyable commands for Windows or Kali. Once the files arrive, the app takes over interpretation.')+(V.authorize(state)?'<div class="callout green section">Scope recorded. Keep the Shark Jack on the approved network only.</div>':'<div class="callout section">You can read these instructions, but do not conduct active tests until authorization is documented in Phase 01.</div>')+payloads()+`<div class="card section"><div class="eyebrow">FILE TRANSFER / ARMED MANAGEMENT MODE</div><h2>Copy results off the Shark Jack</h2><p>Connect the Shark Jack to your computer in its documented management/arming mode. Confirm its current management IP on the Display: <code>172.16.24.1</code> is common on traditional models, but may differ. Connect only to the device's management interface, not the customer's network.</p><label class="form-label" style="max-width:280px">Shark Jack management IPv4<input id="sharkIP" value="${E(guideIP)}" placeholder="172.16.24.1"></label>${platformPicker()}<div class="section"><h3>Transfer step 1 — See which files really exist</h3>${codeCard(commandForTransfer(guideIP,platform,'inspect'),'Inspect saved loot',platform==='kali'?'Kali terminal':'PowerShell','This is a command to run on your computer. It connects by SSH to the Shark Jack and lists /root/loot without assuming a specific payload filename.')}</div><div class="section"><h3>Transfer step 2 — Copy loot to Documents / Kali home</h3>${codeCard(commandForTransfer(guideIP,platform,'transfer'),'Retrieve loot using legacy SCP',platform==='kali'?'Kali terminal':'PowerShell','The -O option avoids the unsupported SFTP subsystem on many embedded devices. If the device uses another path, copy the real path listed above.')}</div><div class="callout blue">If SSH fails: check arming mode, device management IP, physical Ethernet link, static IP configuration if your model requires one, and the configured root password. Never try password guessing. Windows may need its OpenSSH client installed.</div><h3>Transfer step 3 — Upload your evidence</h3>${uploadBox()}<p class="tiny">Best choice: XML (.xml) if available. You can select several .txt/.xml/.nmap/.gnmap files together. Folder/ZIP support depends on browser ZIP format. Keep originals for evidence preservation.</p></div>${navButton('p03','Next: host discovery')}`;}
function uploadBox(){return `<button type="button" id="dropzone" class="drop" data-action="pick"><span class="eyebrow">DROP FILES OR CLICK TO IMPORT</span><strong>Shark Jack • Nmap XML • PowerShell logs</strong><span class="caption">.xml .txt .nmap .gnmap .log .html .zip</span></button>`;}
function hostVerifyTasks(){const platformName=platform;const list=[];if(!V.authorize(state))return [];const targets=V.hostTargets(state);if(!targets.length){for(const scope of V.scopeTargets(state.engagement.scope).slice(0,5))list.push({id:'discover-'+scope,host:scope,label:`Discover devices in ${scope}`,tool:'Nmap',status:'ready',why:'Your imported loot has not established an in-scope host. Run a discovery scan, then upload the XML.',expected:'Nmap XML with responding hosts and port states.',command:C.discoverCommand(scope,platformName)});return list;}
for(const h of targets){const pp=h.ports.filter(x=>x.state==='open');const ports=pp.map(p=>p.port).slice(0,25);const ident=pp.length&&pp.every(p=>p.product||p.version||Object.keys(p.scripts||{}).length>0);const foundSV=(state.uploads.some(u=>(h.sources||[]).includes(u.id)&&/(?:^|\s)-sV(?:\s|$)/.test(u.scanArgs||'')));const flags=ports.length?`nmap -Pn -n -sV -p ${ports.join(',')}`:'nmap -Pn -n -sV --top-ports 1000';const fallback=makeNmap(h.ip,`verify-services`,flags);list.push({id:'h-'+h.ip,host:h.ip,tool:'Nmap',label:`Verify ${h.ip} and ${ports.length?ports.length+' discovered port(s)':'common ports'}`,status:ident?'done':foundSV?'inconclusive':'ready',why:ident?'The imported evidence includes service identity strings; move on to protocol-specific checks.':foundSV?'Version detection ran but identification remains incomplete. This is inconclusive, not a failure; a banner may be hidden. Continue only with relevant follow-up.':'Shark Jack identified this device/port. Confirm its service identity with Nmap before choosing vulnerability tools.',expected:'XML with a host, port state and service fingerprint. Unknown versions are normal on some devices.',command:fallback});}
return list;}
function makeNmap(host,stem,flags){const base=`oac-${C.sanitizeId(host)}-${C.sanitizeId(stem)}`;
if(platform==='kali')return `mkdir -p "$HOME/FieldOps-Loot/Nmap-Results"\n${flags} -oA "$HOME/FieldOps-Loot/Nmap-Results/${base}" ${host}\nls -lh "$HOME/FieldOps-Loot/Nmap-Results/${base}".*`;
return `$Folder=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'FieldOps-Loot\\Nmap Results'\nNew-Item -ItemType Directory -Path $Folder -Force | Out-Null\n$Out=Join-Path $Folder '${base}'\n$Nmap=@('C:\\Program Files (x86)\\Nmap\\nmap.exe','C:\\Program Files\\Nmap\\nmap.exe') | Where-Object {Test-Path $_} | Select-Object -First 1\nif (-not $Nmap) {throw 'Install Nmap from nmap.org/download.html'}\n& $Nmap ${flags.replace(/^nmap /,'')} -oA "$Out" ${host}\nGet-ChildItem "$Out.*" | Select-Object Name,Length`;
}
function attachFileToKnownTarget(meta,text){const name=meta.name;const match=name.match(/((?:\d{1,3}\.){3}\d{1,3})/);const ip=match?.[1]||String(text||'').slice(0,300).match(/(?:^|\s)((?:\d{1,3}\.){3}\d{1,3})/)?.[1];if(!C.validIp(ip))return;const h=state.hosts.find(x=>x.ip===ip);if(!h)return;if(!h.sources.includes(meta.id))h.sources.push(meta.id);const trail=name.slice(name.indexOf(ip)+ip.length).match(/^[-_:](\d{1,5})(?:[-_.]|$)/);const port=trail?Number(trail[1]):null;if(port){const pp=h.ports.find(p=>p.port===port);if(pp&&!pp.sources.includes(meta.id))pp.sources.push(meta.id);meta.evidenceTarget=`${ip}:${port}`;}else meta.evidenceTarget=ip;}
function serviceTasks(){if(!V.authorize(state))return [];return C.getTasks(state,platform).phase05.filter(t=>t.host&&V.canScan(state,t.host)).map(t=>({...t,why:t.why+' The app selects this tool based on the parsed port/service; do not choose a random exploit module.'}));}
function verificationTasks(){let tasks=[];if(!V.authorize(state))return tasks;const found=C.findings(state);for(const x of found){if(!V.canScan(state,x.host))continue;let h=state.hosts.find(h=>h.ip===x.host),p=h?.ports.find(p=>p.port===x.port),cmd='',tool='',how='';if(x.id.endsWith('tls-legacy')){tool='OpenSSL';cmd=platform==='kali'?`openssl s_client -connect ${x.host}:${x.port} -tls1_1 </dev/null 2>&1 | tee "$HOME/FieldOps-Loot/Nmap-Results/${x.host}-${x.port}-tls11-proof.txt"`:`$Base=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'FieldOps-Loot\\Nmap Results'\nopenssl s_client -connect ${x.host}:${x.port} -tls1_1 2>&1 | Tee-Object (Join-Path $Base '${x.host}-${x.port}-tls11-proof.txt')`;how='Attempt only a protocol handshake to corroborate legacy TLS support; handshake success is not proof of compromise.';}
else if(x.id.endsWith('smb1')||x.id.endsWith('smb-sign')){tool='Nmap SMB NSE';cmd=makeNmap(x.host,'smb-confirm',`nmap -Pn -n -p ${x.port} --script smb-protocols,smb2-security-mode`);how='Reconfirm protocol and signing on the specific in-scope Windows host. No authentication or file access.';}
else if(x.id.endsWith('management')){tool='Nmap service fingerprint';cmd=makeNmap(x.host,`${x.port}-management`, `nmap -Pn -n -sV -p ${x.port}`);how='Validate that the listener is still reachable. Confirm firewall/management restrictions with the owner. Do not attempt passwords.';}
else if(x.id.endsWith('version')){tool='SearchSploit (research only)';const product=[p?.product,p?.version].filter(Boolean).join(' ').replace(/[^\w.\- ]/g,'').slice(0,55);cmd=platform==='kali'?`searchsploit -- ${product||'help'}\n# Research references are NOT proof; check vendor advisories and patches.`:`# Run on Kali (not a native PowerShell command):\nsearchsploit -- ${product||'help'}`;how='Look up plausible references offline, confirm exact firmware/build and applicability; no exploit is selected or run automatically.';}
else{tool='Review vendor / host configuration';how=x.verify;}
const proofSeen=(state.uploads||[]).some(u=>u.name.includes('confirm')&&u.name.includes(x.host));tasks.push({...x,command:cmd,tool,how,status:proofSeen?'review':'ready',host:x.host,port:x.port});}
return tasks;}
function renderTask(t,index){const where=platform==='kali'?'Kali Linux terminal':'Windows PowerShell';const referenced=(t.evidenceIds||[]).map(id=>state.uploads.find(u=>u.id===id)).filter(Boolean);return `<div class="card task-card"><div class="split"><div><div class="eyebrow">TEST ${String(index+1).padStart(2,'0')} · ${E(t.host||'AUTHORIZED SUBNET')}${t.port?':'+E(t.port):''}</div><h2>${E(t.label||t.title)}</h2></div>${status(t.status)}</div><p>${E(t.why||t.how||'')}</p><div class="instruction-grid"><div><b>Tool</b><span>${E(t.tool||'Nmap')}</span></div><div><b>Where</b><span>${E(where)}</span></div><div><b>Expected</b><span>${E(t.expected||t.how||'Read-only output')}</span></div></div>${t.command?codeCard(t.command,'Copy and run this entire command',t.tool==='SearchSploit (research only)'?'Kali terminal':where,'Wait until finished. Import the generated .xml or .txt below; FieldOps will re-evaluate findings and decide the next step.'):''}${referenced.length?`<div class="tiny">Linked inputs: ${referenced.map(u=>E(u.name)).join(', ')}</div>`:''}<div class="actions"><button class="btn small primary" data-action="pick">↑ Import results from this test</button><button class="btn small" data-route="assets">Understand this service</button></div></div>`;}
function p03(){const tasks=hostVerifyTasks();return topHero('PHASE 03 / HOST DISCOVERY','Let the loot choose your host checks.','Import discovery logs first. FieldOps identifies the devices and supplies the next Nmap command; no manual note-taking.')+platformPicker()+(!V.authorize(state)?`<div class="callout section">First complete authorization in Phase 01. ${navButton('p01','Open scope form')}</div>`:tasks.length?`<div class="stack section">${tasks.map(renderTask).join('')}</div>`:'<div class="callout section">No in-scope targets yet. Return to Phase 02 and import Shark Jack host discovery results.</div>')+`<div class="card section"><h2>How to finish Phase 03</h2><p>Copy the indicated command, run it in the selected terminal and let Nmap finish. Upload the resulting <code>.xml</code>. FieldOps will read host/port states and mark the next step as ready, done or inconclusive.</p>${uploadBox()}</div>${navButton('p04','Next: service investigations')}`;}
function p04(){const tasks=serviceTasks();return topHero('PHASE 04 / SERVICE INVESTIGATION','Different ports require different tools.','DNS, SMB, HTTP, TLS, SSH and Windows RPC lead to different low-impact tests. These suggestions come from your imported host and service context.')+platformPicker()+(tasks.length?`<div class="stack section">${tasks.map(renderTask).join('')}</div>`:`<div class="card section"><h2>No service-specific tasks yet</h2><p>Either imported loot has no confirmed open ports, scope approval is incomplete, or all hosts are out of scope. Finish Phase 03 and upload service-enumeration XML.</p>${navButton('p03','Back to host checks')}</div>`)+`<div class="card section"><h2>What happens after each import?</h2><p>The parser correlates the target IP + port + protocol, reads supported NSE script outputs, and updates the plain-language interpretation. If the scan produced no useful response, the task becomes <strong>Inconclusive</strong> rather than falsely passing.</p>${uploadBox()}</div>${navButton('p05','Next: vulnerability verification')}`;}
function p05(){const tasks=verificationTasks(),r=V.report(state);return topHero('PHASE 05 / VULNERABILITY VALIDATION','Verify indicators—not guesses.','This phase appears when earlier scans reveal a rule-supported configuration indicator or a version/access-control review candidate.')+`<div class="callout blue section">${r.verified.length} observed configuration indicator(s), ${r.review.length} unverified review candidate(s), ${r.pending} protocol validation task(s) remaining. None of those counts is proof of successful exploitation.</div>`+platformPicker()+(tasks.length?`<div class="stack section">${tasks.map(renderTask).join('')}</div>`:`<div class="card section"><h2>No supported vulnerability indicator from the current evidence</h2><p>The app cannot infer vulnerabilities merely because a port is open. Check Phase 04 for pending tests, or move to Phase 07 and document that no supported weakness was confirmed.</p></div>`)+`<div class="card section"><h2>Want to research a possible exploit?</h2><p>For a recognized product/version, run <code>searchsploit</code> on Kali or inspect a potential Metasploit module using <code>search</code> and <code>info</code>. This is <strong>research only</strong>. The module must match the exact software, patch level and lab conditions; it is not a finding just because a match exists.</p>${navButton('p06','Controlled proof guidance')}</div>`;}
function p06(){const finds=C.findings(state),allowed=V.authorize(state)&&state.engagement.proofApproved;const hosts=V.hostTargets(state);return topHero('PHASE 06 / CONTROLLED PROOF','Document actual outcomes, not imaginary exploits.','Use this phase only for an explicitly approved target. The tool can interpret supported test logs, but does not choose or execute arbitrary exploits.')+`<div class="callout ${allowed?'green':'blue'} section">${allowed?'Controlled proof is marked approved in your scope record. Verify each tool/module and permitted impact before executing it.':'Controlled proof is NOT marked approved. You may review tool documentation, but do not run intrusive proof or post-exploitation commands.'}</div>`+(finds.length?`<div class="stack section">${finds.filter(f=>V.canScan(state,f.host)).map((x,i)=>{const h=state.hosts.find(h=>h.ip===x.host),p=h?.ports.find(p=>p.port===x.port),info=p?V.proofCommands(state,h,p):null;return `<div class="card"><div class="eyebrow">POTENTIAL RESEARCH LEAD ${i+1}</div><h2>${E(x.host)}:${E(x.port)} — ${E(x.title)}</h2><p>${E(x.why)}</p><div class="callout blue">Status: ${x.status==='observed'?'configuration indicator observed':'requires verification'}. A matching SearchSploit/Metasploit reference is not confirmation of a vulnerability.</div>${info?`<h3>Research on Kali only</h3><p>Start by verifying the exact affected version and prerequisites. On Kali, find candidate references; with Metasploit, inspect <code>info &lt;module&gt;</code>, <code>show options</code> and the module's documented impact. Run only a specifically authorized, matched proof in an isolated lab. Save the complete console output for import. Do not use post-exploitation actions that collect credentials, personal data or establish persistence.</p>${codeCard(info.searchsploit,'Look up offline references','Kali terminal',info.warning)}${codeCard(info.metasploit,'Inspect possible Metasploit modules','Kali terminal','Only use search/info for module review. Confirm software build and required conditions; never run a module without explicit authorization.')}`:''}</div>`;}).join('')}</div>`:'<div class="card section"><h2>No supported exploit candidate has been established</h2><p>That is a valid result, not an app failure. Complete validation scans first or document that no controlled exploitation was performed.</p></div>')+`<div class="card section"><h2>Import a controlled test or post-exploitation log</h2><p>For evidence linking, choose the target from the observed in-scope inventory and upload the real console log. FieldOps will classify known success/failure markers conservatively. The report will never claim access or impact solely from an open port.</p><label class="form-label" style="max-width:300px">Target that produced the log<select id="proofTarget"><option value="">Select matching asset</option>${hosts.map(h=>`<option value="${E(h.ip)}" ${selectedProofTarget===h.ip?'selected':''}>${E(h.ip)} ${E(h.hostname)}</option>`).join('')}</select></label><div class="actions"><button class="btn primary" data-action="proofUpload" ${!allowed?'disabled':''}>↑ Import approved proof log</button></div><input type="file" id="proofFile" hidden accept=".txt,.log,.nmap,.json"><div class="evi-list">${(state.proofs||[]).map(p=>`<div class="evi-row"><div><strong>${E(p.target)} · ${E(p.name)}</strong><p class="caption">${E(p.notes)}</p><span class="tag ${p.kind==='session-claimed'?'review':'muted'}">${E(p.kind)}</span></div></div>`).join('')||'<p class="caption">No controlled proof has been imported. Report will say: Not performed / not established.</p>'}</div><div class="callout blue section">Session logs are operator-supplied evidence, not independently verified proof. Do not collect credentials, export sensitive files, establish persistence, or test beyond the written authorization. Post-exploitation impact requires separate, minimal, documented validation.</div></div>${navButton('p07','Finalize report')}`;}
function findingsCards(){const f=C.findings(state);return f.length?f.map(x=>`<div class="card section"><div class="split"><div><div class="eyebrow">${E(x.host)}:${x.port}/${E(x.proto)}</div><h2>${E(x.title)}</h2></div>${status(x.status)}</div><p><strong>Why this was flagged:</strong> ${E(x.why)}</p><p><strong>What confirms it:</strong> ${E(x.verify)}</p><p><strong>Recommended remediation:</strong> ${E(x.fix)}</p><p class="tiny">Evidence: ${V.sourceList(state,x.sources).map(x=>E(x.name)).join(', ')||'No supported source'}</p></div>`).join(''):'<div class="callout blue">No supported vulnerability indicator identified by the current rule set. This does not prove the tested systems are secure.</div>';}
function assetsView(){return topHero('INVENTORY / AUTO-INTERPRETATION','What did the scans actually discover?','Every host, port and service appears with a plain-language explanation, associated evidence and its next appropriate action.')+metrics()+`<div class="stack section">${state.hosts.map(h=>`<div class="card"><div class="split"><div><div class="eyebrow">HOST ${E(h.ip)}</div><h2>${E(h.hostname||'Unnamed device')}</h2><p class="caption">MAC: ${E(h.mac||'Not reported')} • ${V.canScan(state,h.ip)?'Inside scope':'OUTSIDE authorized scope — commands suppressed'}</p></div><span class="tag ${V.canScan(state,h.ip)?'good':'bad'}">${h.ports.filter(x=>x.state==='open').length} open port(s)</span></div><div class="stack">${h.ports.filter(x=>x.state==='open').map(p=>{const next=V.nextStep(state,h,p,platform);return `<div class="service-box"><div class="split"><strong>${E(p.port)}/${E(p.proto)} · ${E(p.service||'unknown')} ${E(p.product||'')} ${E(p.version||'')}</strong><span class="tag">${E(p.state)}</span></div><p>${E(V.serviceSummary(h,p))}</p><p><strong>Next:</strong> ${E(next.label)}. ${E(next.reason)}</p><p class="tiny">Source: ${V.sourceList(state,p.sources).map(u=>E(u.name)).join(', ')||'Not linked'}</p></div>`;}).join('')||'<p>No confirmed open ports yet. A host being reachable does not establish service exposure.</p>'}</div></div>`).join('')||'<div class="card"><h2>Import a Shark Jack or Nmap file first.</h2></div>'}</div>`;}
function evidenceRows(){return state.uploads.slice().reverse().map(u=>`<div class="evi-row"><div><strong>${E(u.name)}</strong><div class="tiny">${E(V.categorizeUpload(u))} · ${u.hostCount} host(s), ${u.portCount} port records · ${u.complete?'Scanner completion marker present':'Completion not established'}</div><p class="caption">${E(V.summaryForUpload(u))}</p><div class="tiny">SHA-256: ${E(u.sha||'Not available')} ${u.evidenceTarget?' • Linked: '+E(u.evidenceTarget):''}</div>${u.notes?.length?`<p class="tiny">Notes: ${u.notes.map(E).join(' • ')}</p>`:''}</div><div class="actions"><button class="btn small" data-action="viewraw" data-id="${E(u.id)}">View</button><button class="btn small danger" data-action="remove" data-id="${E(u.id)}">Remove</button></div></div>`).join('')||'<div class="card">No evidence imported yet. Begin with Shark Jack payloads in Phase 02.</div>';}
function evidenceView(){return topHero('EVIDENCE / LOCAL IMPORT','Upload files. The tool does the interpretation.','Import a batch of Nmap XML, Shark Jack text/loot, or previous reports; do not manually type port findings.')+uploadBox()+`<div class="card section"><h2>Parsed evidence (${state.uploads.length})</h2><p>Duplicate SHA-256 files are ignored. HTML report imports are marked historical inventory only. Raw file text is encrypted with your vault while space permits; always retain the original source files independently.</p><div class="evi-list">${evidenceRows()}</div></div><div class="card section"><h2>Import from v9 (optional)</h2><p>If your previous v9 workspace remains in this browser profile, import its recognized hosts and scan evidence into v10 without deleting the old v9 data. This includes existing evidence only when it is accessible in that browser.</p><button data-action="migrate" class="btn" ${!oldDataExists()?'disabled':''}>${oldDataExists()?'Import existing v9 assessment':'No v9 workspace detected'}</button></div><div class="card section"><h2>Backup, restore and reset</h2><div class="actions"><button class="btn" data-action="backup">Export encrypted vault</button><button class="btn" data-action="restore">Restore encrypted v10 backup</button><button class="btn danger" data-action="reset">Reset v10 workspace</button></div><p class="tiny">A backup is encrypted with the v10 passphrase and contains the current working data; it does not include data from other app versions.</p></div>`;}
function reportHtml(){const rpt=V.report(state),e=state.engagement,linkIds=ids=>V.sourceList(state,ids).map(x=>x.name).join('; ')||'Not linked';return `<article class="print-report"><div class="eyebrow">OAC // FIELDOPS // v10</div><h1>${E(e.name||'Assessment')}</h1><p>Evidence-driven network assessment • ${E(e.date||'')} • Generated ${E(new Date().toLocaleString())}</p><h2>Engagement and permission record</h2><table><tr><th>Owner</th><td>${E(e.owner||'Not recorded')}</td><th>Assessor</th><td>${E(e.operator||'Not recorded')}</td></tr><tr><th>Authorized scope</th><td>${E(e.scope||'Not recorded')}</td><th>Consent record</th><td>${E(e.consentRecord||'Not recorded')}</td></tr><tr><th>Authorized</th><td>${e.authorized?'Claimed by operator':'Not recorded'}</td><th>Controlled proof approved</th><td>${e.proofApproved?'Operator confirmed':'No'}</td></tr></table><p>Exclusions: ${E(e.exclusions||'Not listed')}</p><h2>Executive summary</h2><p>${E(rpt.summary)}</p><h2>Observed assets and services</h2><table><tr><th>Host</th><th>Port / protocol</th><th>Service fingerprint</th><th>Evidence</th></tr>${state.hosts.flatMap(h=>(h.ports.filter(p=>p.state==='open').length?h.ports.filter(p=>p.state==='open'):[null]).map(p=>`<tr><td>${E(h.ip)} ${E(h.hostname)}</td><td>${p?`${p.port}/${E(p.proto)}`:'No confirmed open ports'}</td><td>${p?E([p.service,p.product,p.version].filter(Boolean).join(' ')):'—'}</td><td>${p?E(linkIds(p.sources)):E(linkIds(h.sources))}</td></tr>`)).join('')}</table><h2>Security observations and verification needs</h2>${rpt.all.length?rpt.all.map((x,i)=>`<section><h3>${i+1}. ${E(x.title)} — ${E(x.host)}:${x.port}</h3><p><strong>Status:</strong> ${x.status==='observed'?'Observed configuration indicator, not proven exploit':'Unverified review candidate'}</p><p><strong>Basis:</strong> ${E(x.why)}</p><p><strong>How to verify:</strong> ${E(x.verify)}</p><p><strong>Remediation:</strong> ${E(x.fix)}</p><p><strong>Linked source:</strong> ${E(linkIds(x.sources))}</p></section>`).join(''):'<p>No supported positive security indicator was detected. This is not a clean-security certification; review assessment coverage and pending tests.</p>'}<h2>Exploitation and post-exploitation outcomes</h2>${rpt.proof.length?rpt.proof.map(p=>`<section><h3>${E(p.target)} — ${E(p.kind)}</h3><p>${E(p.notes)}</p><p>Log: ${E(p.name)} · SHA-256: ${E(p.sha||'unavailable')}</p><p>Interpretation limit: Operator-provided tool output, not an independently corroborated compromise, business impact or cleanup verification.</p></section>`).join(''):'<p>Controlled exploitation: Not performed or not evidenced. Successful exploitation: Not established. Post-exploitation: Not performed or not evidenced.</p>'}<h2>Remediation priorities</h2>${rpt.all.length?`<ol>${rpt.all.map(x=>`<li>${E(x.host)}:${x.port}: ${E(x.fix)} ${x.status==='review'?'(verify applicability first)':''}</li>`).join('')}</ol>`:'<p>No confirmed remediation item from the supplied evidence. Investigate unfinished checks and maintain supported software/firmware.</p>'}<h2>Research and supplemental logs</h2><table><tr><th>Log</th><th>Interpretation</th><th>Target link</th></tr>${state.uploads.filter(u=>u.analysisType).map(u=>`<tr><td>${E(u.name)}</td><td>${E(V.summaryForUpload(u))}</td><td>${E(u.evidenceTarget||'Not reliably attributable')}</td></tr>`).join('')||'<tr><td colspan="3">No supplemental logs uploaded.</td></tr>'}</table><h2>Assessment limits</h2><ul>${rpt.limitations.map(x=>`<li>${E(x)}</li>`).join('')}</ul><h2>Evidence manifest</h2><table><tr><th>Filename</th><th>SHA-256</th><th>Interpretation</th></tr>${state.uploads.map(u=>`<tr><td>${E(u.name)}</td><td class="mono">${E(u.sha)}</td><td>${E(V.summaryForUpload(u))}</td></tr>`).join('')}</table><p class="tiny">Locally generated report. The app does not certify scope permission, scanner accuracy, CVE applicability or exploitation.</p></article>`;}
function reportView(){return topHero('PHASE 07 / AUTOMATIC REPORT','A defensible report, without manual finding entry.','The summary, asset inventory, observations, recommendations and evidence hashes are generated from your uploads.')+`<div class="actions section"><button class="btn primary" data-action="htmlReport">↓ Export HTML report</button><button class="btn" data-action="print">Print / Save PDF</button><button class="btn" data-action="backup">Export encrypted project backup</button></div><div class="report-paper section">${reportHtml()}</div>`;}
function render(){if(!state){lockedView();return;}cmdMap.clear();let routes={overview:['MISSION OVERVIEW',overview],p01:['01 · AUTHORIZATION',authView],p02:['02 · SHARK JACK',sharkView],p03:['03 · HOST DISCOVERY',p03],p04:['04 · SERVICE ENUMERATION',p04],p05:['05 · VULNERABILITY CHECKS',p05],p06:['06 · PROOF & IMPACT',p06],p07:['07 · REPORT & CLOSURE',reportView],evidence:['EVIDENCE INBOX',evidenceView],assets:['ASSETS & SERVICES',assetsView]};const [label,fn]=routes[route]||routes.overview;$('#main').innerHTML=fn();$('#crumb').textContent=label;document.querySelectorAll('[data-route]').forEach(el=>{if(el.closest('#sidebar'))el.classList.toggle('selected',el.dataset.route===route);});}
function navigate(where){route=where;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
async function sha256(buf){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',buf))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function unzip(file){const array=new Uint8Array(await file.arrayBuffer()),d=new DataView(array.buffer),decoder=new TextDecoder();let end=-1;for(let n=array.length-22;n>=Math.max(0,array.length-65557);n--){if(d.getUint32(n,true)===0x06054b50){end=n;break;}}if(end<0)throw Error('Cannot locate ZIP directory');let count=Math.min(250,d.getUint16(end+10,true)),at=d.getUint32(end+16,true),out=[];for(let i=0;i<count;i++){if(d.getUint32(at,true)!==0x02014b50)throw Error('Invalid ZIP');let meth=d.getUint16(at+10,true),size=d.getUint32(at+20,true),length=d.getUint32(at+24,true),nl=d.getUint16(at+28,true),xl=d.getUint16(at+30,true),cl=d.getUint16(at+32,true),offset=d.getUint32(at+42,true),name=decoder.decode(array.slice(at+46,at+46+nl));at+=46+nl+xl+cl;if(name.endsWith('/')||!/\.(xml|txt|log|gnmap|nmap|csv|html)$/i.test(name)||size>2e6||length>3e6)continue;const localNl=d.getUint16(offset+26,true),localEx=d.getUint16(offset+28,true),start=offset+30+localNl+localEx;let body=array.slice(start,start+size);if(meth===8){if(typeof DecompressionStream==='undefined')throw Error('ZIP decompression unsupported; extract it first');body=new Uint8Array(await new Response(new Blob([body]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());}else if(meth!==0)continue;if(body.length>3e6)continue;out.push({name:name.split('/').pop(),text:decoder.decode(body),bytes:body});}if(!out.length)throw Error('No compatible logs in ZIP. Extract ZIP locally and upload XML/TXT instead.');return out;}
async function processUpload(files){await mutate(async()=>{let added=0,errors=[];for(const f of files){try{let entries=/\.zip$/i.test(f.name)?await unzip(f):[{name:f.name,text:await f.text(),bytes:new Uint8Array(await f.arrayBuffer())}];for(const entry of entries){if(entry.bytes.byteLength>3e6){errors.push(entry.name+': file over 3 MB');continue;}const digest=await sha256(entry.bytes);if(state.uploads.some(u=>u.sha===digest))continue;let parsed;try{parsed=C.parseEvidence(entry.name,entry.text);}catch(err){parsed={format:'unparsed',hosts:[],complete:false,scanArgs:'',notes:['Parser: '+err.message]};}const id=crypto.randomUUID(),raw=entry.text;const meta={id,name:entry.name,sha:digest,date:new Date().toISOString(),format:parsed.format,complete:parsed.complete,scanArgs:parsed.scanArgs,notes:parsed.notes||[],hostCount:parsed.hosts.length,portCount:parsed.hosts.reduce((n,h)=>n+h.ports.length,0),bytes:entry.bytes.byteLength,analysisType:V.analyzeText(entry.name,entry.text)};state.uploads.push(meta);C.mergeEvidence(state,parsed,meta);attachFileToKnownTarget(meta,entry.text);if(raw.length+rawTotal()<1500000&&raw.length<700000)state.raw[id]=raw;else{state.raw[id]=raw.slice(0,15000);meta.notes.push('Preview only retained in encrypted vault due to storage size. Keep the original file.');}added++;}}
catch(ex){errors.push(f.name+': '+ex.message);}}if(errors.length)alert('Skipped or partially processed:\n'+errors.join('\n'));toast(added+' evidence file(s) imported and interpreted.');});if(state&&V.authorize(state)&&files.length)navigate(actionAdvice().route);}
async function rebuild(){state.hosts=[];for(const u of state.uploads){const raw=state.raw[u.id];if(!raw){u.notes=[...(u.notes||[]),'Raw bytes not available; reimport this source if needed.'];continue;}try{const parsed=C.parseEvidence(u.name,raw);C.mergeEvidence(state,parsed,u);attachFileToKnownTarget(u,raw);}catch(err){u.notes.push('Reparse failed: '+err.message);}}}
async function migrateV9(){const old=JSON.parse(localStorage.getItem(OLD)||'null');if(!old||old.version!==9||!Array.isArray(old.uploads))throw Error('No recognized v9 workspace');const n=old.uploads.filter(u=>!state.uploads.some(v=>v.sha===u.sha));let raws={};try{const db=await new Promise((ok,no)=>{let q=indexedDB.open('oacFieldOpsV9Files',1);q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)});for(const u of n){const txt=await new Promise(ok=>{const req=db.transaction('files').objectStore('files').get(u.id);req.onsuccess=()=>ok(req.result?.text||null);req.onerror=()=>ok(null)});if(txt)raws[u.id]=txt;}db.close();}catch(err){console.warn('v9 raw evidence unavailable',err);}
state.engagement={...state.engagement,...old.engagement,consentRecord:state.engagement.consentRecord||''};state.engagement.authorized=false;state.engagement.proofApproved=false;for(const u of n){const copy={...u,notes:[...(u.notes||[]),'Migrated from v9; verify raw evidence/provenance.']};state.uploads.push(copy);const raw=raws[u.id];if(raw&&raw.length+rawTotal()<1500000){state.raw[u.id]=raw;try{C.mergeEvidence(state,C.parseEvidence(u.name,raw),copy);}catch{}}else{state.raw[u.id]=(u.preview||'').slice(0,15000);copy.notes.push('Raw evidence unavailable in this browser; reimport for verification.');}}
await rebuild();toast(n.length+' v9 metadata records migrated. Reconfirm Phase 01 authorization.');}
async function addProof(file){if(!selectedProofTarget||!V.canScan(state,selectedProofTarget)||!state.engagement.proofApproved)throw Error('Select an authorized target and approve controlled proof in Phase 01');const txt=await file.text(),dig=await sha256(new Uint8Array(await file.arrayBuffer())),out=V.proofReview(txt),id=crypto.randomUUID();state.proofs.push({id,target:selectedProofTarget,name:file.name,sha:dig,kind:out.kind,notes:out.notes,date:new Date().toISOString()});if(txt.length+rawTotal()<1500000)state.raw[id]=txt;else state.raw[id]=txt.slice(0,15000);toast('Proof log interpreted; report updated.');}
function exportHtml(){download(`OAC-FieldOps-V10-Report-${stamp()}.html`,`<!doctype html><html lang="en"><meta charset="utf-8"><title>OAC FieldOps v10 Report</title><style>body{font:14px/1.55 Arial;color:#263746;max-width:1000px;margin:30px auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border-bottom:1px solid #ccd6dd;padding:9px;text-align:left;vertical-align:top}h2{margin-top:25px;border-bottom:1px solid #bdc9d3;padding-bottom:7px}section{break-inside:avoid}p{white-space:pre-wrap}.tiny,.eyebrow{font-size:11px;color:#647384}.mono{overflow-wrap:anywhere} @page{margin:15mm}@media print{body{margin:0}}</style>${reportHtml()}</html>`,'text/html');}
async function copyCmd(id){const s=cmdMap.get(id);if(!s)return;try{await navigator.clipboard.writeText(s);toast('Command copied.');}catch{const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();document.execCommand('copy');t.remove();toast('Command copied.');}}
async function action(event){const nav=event.target.closest('[data-route]');if(nav){navigate(nav.dataset.route);return;}const copy=event.target.closest('[data-copy]');if(copy){await copyCmd(copy.dataset.copy);return;}const plat=event.target.closest('[data-platform]');if(plat){platform=plat.dataset.platform;render();return;}const btn=event.target.closest('[data-action]');if(!btn)return;const name=btn.dataset.action,id=btn.dataset.id;try{switch(name){case'lock':lock();break;case'pick':$('#files').click();break;case'backup':{await writePromise;const data=localStorage.getItem(KEY);if(data)download(`OAC-FieldOps-V10-Encrypted-Backup-${stamp()}.json`,data,'application/json');toast('Encrypted vault exported.');break;}case'restore':$('#restore').click();break;case'migrate':if(confirm('Import existing v9 host and evidence records into this v10 vault? v9 will remain unchanged. You must reconfirm authorization.'))await mutate(migrateV9);break;case'viewraw':{const u=state.uploads.find(x=>x.id===id);download(u?.name||'evidence.txt',state.raw[id]||'Raw evidence unavailable');break;}case'remove':if(confirm('Remove evidence and rebuild derived inventory?'))await mutate(async()=>{state.uploads=state.uploads.filter(u=>u.id!==id);delete state.raw[id];await rebuild();});break;case'reset':{if(!confirm('Reset the current v10 assessment? This will delete ALL v10 records in this vault. Export an encrypted backup first.'))return;if(prompt('Type RESET to confirm (not your password):')!=='RESET')return;await mutate(async()=>{state=V.newState();});navigate('p01');break;}case'proofUpload':$('#proofFile').click();break;case'htmlReport':exportHtml();break;case'print':window.print();break;}}
catch(err){alert(err.message);}}
async function authForm(event){event.preventDefault();const d=new FormData(event.target);await mutate(async()=>{const scope=String(d.get('scope')||'').trim();if(!V.validScope(scope))throw Error('Enter valid IPv4 addresses or CIDR blocks only. Example: 10.10.10.0/24');if(!d.get('name')||!d.get('owner')||!d.get('consentRecord'))throw Error('Name, owner and consent record are required');state.engagement={...state.engagement,name:String(d.get('name')),owner:String(d.get('owner')),operator:String(d.get('operator')||''),date:String(d.get('date')||''),scope,authorizationType:String(d.get('authorizationType')||'self'),approval:String(d.get('approval')||''),exclusions:String(d.get('exclusions')||''),consentRecord:String(d.get('consentRecord')||''),authorized:d.get('authorized')==='on',proofApproved:d.get('proofApproved')==='on'};toast('Scope and consent record saved.');});if(V.authorize(state))navigate('p02');}
function listeners(){document.addEventListener('click',e=>{if(e.target.id==='mobileNav'){$('#sidebar').classList.toggle('open');return;}action(e);});document.addEventListener('submit',async e=>{if(e.target.id==='vaultForm'){e.preventDefault();try{await authenticate(e.target)}catch(err){alert('Vault unlock failed: '+err.message)}return;}if(e.target.id==='authDetails')return authForm(e);});document.addEventListener('change',async e=>{if(e.target.id==='files'){const fs=arr(e.target.files);if(fs.length)await processUpload(fs);e.target.value='';}if(e.target.id==='sharkIP'){if(C.validIp(e.target.value)){guideIP=e.target.value;render();}else alert('Enter a valid IPv4 address');}if(e.target.id==='proofTarget')selectedProofTarget=e.target.value;if(e.target.id==='proofFile'){let f=e.target.files?.[0];if(f)await mutate(()=>addProof(f));e.target.value='';}if(e.target.id==='restore'){const f=e.target.files?.[0];if(f){try{let str=await f.text(),p=prompt('Enter the passphrase of this encrypted backup:');if(!p)return;const o=await openVault(p,str);if(!confirm('Replace current v10 workspace with backup? Export current vault first.'))return;state=o.data;passKey=o.key;saltForSession=o.salt;localStorage.setItem(KEY,str);render();toast('Encrypted v10 vault restored.');}catch(err){alert('Restore failed: '+err.message)}}e.target.value='';}});document.addEventListener('dragover',e=>{if(e.dataTransfer?.types?.includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if(state&&e.dataTransfer?.files?.length){e.preventDefault();processUpload(arr(e.dataTransfer.files));}});}
listeners();if(!crypto?.subtle||!localStorage){$('#auth').innerHTML='<h2>This app requires an HTTPS browser with Web Crypto and localStorage enabled.</h2>';}else lockedView();
})();
